24	function logEvent(level: 'info' | 'warning' | 'error', event: string, data: Record<string, unknown> = {}) {
25	  const payload = { ts: new Date().toISOString(), function: 'process-requisition-ai', event, ...data };
26	  if (level === 'error') console.error('[AI]', JSON.stringify(payload));
27	  else if (level === 'warning') console.warn('[AI]', JSON.stringify(payload));
