345	// Função para retry com backoff exponencial
346	async function retryWithBackoff(fn, maxRetries = 3, baseDelay = 1000) {
347	  let lastError;
348	  for (let attempt = 0; attempt <= maxRetries; attempt++) {
349	    try {
350	      return await fn();
351	    } catch (error) {
352	      lastError = error;
353	      // Se é o último attempt, lança o erro
354	      if (attempt === maxRetries) {
355	        throw lastError;
356	      }
357	      // Calcular delay com backoff exponencial
358	      const delay = baseDelay * Math.pow(2, attempt);
359	      console.log(`❌ Tentativa ${attempt + 1} falhou: ${lastError.message}. Tentando novamente em ${delay}ms...`);
360	      // Aguardar antes da próxima tentativa
361	      await new Promise((resolve) => setTimeout(resolve, delay));
362	    }
363	  }
364	  throw lastError;
365	}
366	// Função para fazer requisições à API do OpenRouter com fallback de modelo
367	async function makeOpenRouterRequestWithModel(prompt, model) {
368	  const apiKey = Deno.env.get('OPENROUTER_API_KEY');
369	  if (!apiKey) {
370	    throw new Error('OPENROUTER_API_KEY not set');
371	  }
372	  const fetchStart = Date.now();
373	  const response = await fetch('https://openrouter.ai/api/v1/chat/completions', {
374	    method: 'POST',
375	    headers: {
376	      'Authorization': `Bearer ${apiKey}`,
377	      'Content-Type': 'application/json',
378	      'HTTP-Referer': 'https://momma-stock-insight.vercel.app',
379	      'X-Title': 'momma-manual'
380	    },
381	    body: JSON.stringify({
382	      model: model,
383	      messages: [
384	        { role: 'system', content: SYSTEM_PROMPT },
385	        { role: 'user', content: prompt }
386	      ],
387	      temperature: 0.1,
388	      response_format: { type: 'json_object' }
389	    })
390	  });
391	  if (!response.ok) {
392	    const errorText = await response.text().catch(() => 'Erro desconhecido');
393	    console.error(`❌ OpenRouter API error with model ${model}: ${response.status} - ${errorText}`);
394	    logEvent('warning', 'fallback_api_error', { model, status: response.status, errorText });
395	    // Diferentes tipos de erro
396	    if (response.status === 502) {
397	      throw new Error(`OpenRouter API temporariamente indisponível (502 Bad Gateway). Tentando novamente...`);
398	    } else if (response.status === 503) {
399	      throw new Error(`OpenRouter API sobrecarregada (503 Service Unavailable). Tentando novamente...`);
400	    } else if (response.status === 429) {
401	      throw new Error(`Rate limit atingido (429 Too Many Requests). Tentando novamente...`);
402	    } else if (response.status >= 500) {
403	      throw new Error(`Erro interno do servidor OpenRouter (${response.status}). Tentando novamente...`);
404	    } else {
405	      // Erros 4xx não devem ser retentados
406	      throw new Error(`OpenRouter API error: ${response.status} - ${errorText}`);
407	    }
408	  }
409	  const data = await response.json();
410	  const durationMs = Date.now() - fetchStart;
411	  return { data, durationMs, model };
412	}
413	// Função para fazer requisições à API do OpenRouter com retry e fallback de modelo
414	// Returns { data, durationMs, model } from makeOpenRouterRequestWithModel
415	async function makeOpenRouterRequest(prompt) {
416	  let lastError;
417	  for (const model of FALLBACK_MODELS) {
418	    try {
419	
420	      const res = await retryWithBackoff(async () => {
421	        return await makeOpenRouterRequestWithModel(prompt, model);
422	      }, 3, 2000);
423	      return res;
424	    } catch (err) {
425	      lastError = err;
426	      logEvent('warning', 'fallback_model_fail', { model, error: err instanceof Error ? err.message : String(err) });
427	      continue;
428	    }
429	  }
430	  throw lastError || new Error('Todos os modelos de fallback falharam');
431	}
432	// Streaming de raciocínio via SSE com fallback de modelo
433	async function streamOpenRouterReasoning(prompt, models, tracer?: EdgeTracer, metrics?: EdgeMetrics) {
434	  const encoder = new TextEncoder();
435	  let chosenModelIndex = -1;
436	  let contentBuffer = '';
437	  let reasoningBuffer = '';
438	  let normalizedReasoningSent = '';
439	  let seenTextDelta = false;
440	  let modelAnnounced = false;
441	  const stream = new ReadableStream({
442	    async start(controller) {
443	      // Helper para enviar evento SSE
444	      const sendEvent = (event, data) => {
445	        const payload = `event: ${event}\n` + `data: ${JSON.stringify(data)}\n\n`;
446	        controller.enqueue(encoder.encode(payload));
447	      };
448	      sendEvent('status', { message: 'Processando IA...' });
449	      // Tenta modelos em sequência
450	      for (let i = 0; i < models.length; i++) {
451	        const model = models[i];
452	        try {
453	          chosenModelIndex = i;
454	          const apiKeyStream = Deno.env.get('OPENROUTER_API_KEY');
455	          if (!apiKeyStream) {
456	            throw new Error('OPENROUTER_API_KEY not set');
457	          }
458	          if (isGrokModel(model)) {
459	            const grokFetchStart = Date.now();
460	            const res = await fetch('https://openrouter.ai/api/v1/chat/completions', {
461	              method: 'POST',
462	              headers: {
463	                'Authorization': `Bearer ${apiKeyStream}`,
464	                'Content-Type': 'application/json',
465	                'HTTP-Referer': 'https://momma-stock-insight.vercel.app',
466	                'X-Title': 'momma-manual'
467	              },
468	              body: JSON.stringify({
469	                model,
470	                messages: [ { role: 'system', content: SYSTEM_PROMPT }, { role: 'user', content: prompt } ],
471	                temperature: 0.1,
472	                response_format: { type: 'json_object' }
473	              })
474	            });
475	            if (!res.ok) {
476	              const txt = await res.text().catch(() => '');
477	              logEvent('warning', 'fallback_model_fail', { model, status: res.status, errorText: txt });
478	              throw new Error(`Falha request ${model}: ${res.status} ${txt}`);
479	            }
480	            const data = await res.json();
481	            const grokDurationMs = Date.now() - grokFetchStart;
482	            const content = data?.choices?.[0]?.message?.content ?? '';
483	            logEvent('info', 'openrouter_response', { model, contentLength: content.length, content });
484	            // Record telemetry metrics for Grok non-streaming response
485	            if (metrics && data?.usage) {
486	              const grokInputTokens = data.usage.prompt_tokens ?? 0;
487	              const grokOutputTokens = data.usage.completion_tokens ?? 0;
488	              metrics.recordLlmCall({
489	                model: data.model || model,
490	                provider: 'openrouter',
491	                operation: 'requisition-parse',
492	                inputTokens: grokInputTokens,
493	                outputTokens: grokOutputTokens,
494	                durationMs: grokDurationMs,
495	              });
496	            }
497	            let parsedResponse = null;
498	            try {
499	              let clean = content.trim();
500	              if (clean.startsWith('```')) {
501	                clean = clean.replace(/^```(?:json)?\s*/, '').replace(/\s*```$/, '');
502	              }
503	              parsedResponse = JSON.parse(clean);
504	            } catch {
505	              sendEvent('error', { message: 'Erro ao processar resposta da IA' });
