96	    } catch (err) {
97	      lastErr = err;
98	      console.warn('[review] model fail', model, err instanceof Error ? err.message : String(err));
99	    }
100	  }

1	/**
2	 * @module types/drp
3	 *
4	 * Tipos do módulo DRP (Distribution Requirements Planning) — Plano de Reposição.
5	 *
6	 * O DRP calcula sugestões de envio fábrica → lojas com base em demanda
7	 * histórica DoW-aware (dia da semana), estoque atual e em-trânsito.
8	 *
9	 * Algoritmo: forecast = Σ µ_dow_loja_produto sobre dias do horizonte;
10	 * SS = Z × √Σσ²; sugestão = max(0, forecast + SS - estoque - em_trânsito).
11	 *
12	 * Restrição dura: shelf-life uniforme 5d — bloqueia se horizonte excede 5d.
13	 */
14	
15	/** Identificador de loja (loja_id em produtos_master, estoque, etc.). */
16	export type LojaId = 1 | 2 | 3 | 4 | 5 | 6;
17	
18	/** Lookback histórico em dias (ou 'all' = vida toda). */
19	export type DrpLookback = 30 | 60 | 90 | 180 | 'all';
20	
21	/** Z-score do service level (1.28=90%, 1.65=95%, 1.96=97.5%, 2.33=99%). */
22	export type DrpServiceLevelZ = 1.28 | 1.65 | 1.96 | 2.33;
23	
24	/** Map Z-score → label legível. */
25	export const SERVICE_LEVEL_LABELS: Record<DrpServiceLevelZ, string> = {
26	  1.28: '90%',
27	  1.65: '95%',
28	  1.96: '97.5%',
29	  2.33: '99%',
30	};
31	
32	/** Constante de shelf-life uniforme em dias (Momma é doces frescos, 5d max). */
33	export const SHELF_LIFE_DAYS = 5;
34	
35	/** Status visual de uma loja na timeline do DRP. */
