184	/** Formata ISO YYYY-MM-DD em dd/mm/yyyy (formato BR). */
185	export function formatBrDate(iso: string | null | undefined): string {
186	  if (!iso) return '—';
187	  const [y, m, d] = iso.split('T')[0].split('-');
188	  if (!y || !m || !d) return iso;
189	  return `${d}/${m}/${y}`;
190	}
