49	CREATE OR REPLACE FUNCTION public.drp_gerar_requisicoes(plano JSONB)
50	RETURNS JSONB
51	LANGUAGE plpgsql
52	SECURITY DEFINER
53	SET search_path = public, pg_temp
54	AS $$
55	DECLARE
56	  v_user_id UUID := auth.uid();
57	  v_data_chegada DATE := (plano->>'data_chegada')::DATE;
58	  v_data_durar_ate DATE := (plano->>'data_durar_ate')::DATE;
59	  v_user_name TEXT := COALESCE(plano->>'user_name', 'Sistema');
60	  v_preparador TEXT := COALESCE(plano->>'preparador', 'Fábrica');
61	  v_plans JSONB := plano->'plans';
62	  v_plan JSONB;
63	  v_item JSONB;
64	  v_idem_key TEXT;
65	  v_loja_id INTEGER;
66	  v_loja_nome TEXT;
67	  v_existing_id INTEGER;
68	  v_new_req_id INTEGER;
69	  v_qtd_itens INTEGER;
70	  v_qtd_unidades INTEGER;
71	  v_results JSONB := '[]'::JSONB;
72	  v_result_item JSONB;
73	  v_obs TEXT;
74	  v_role_name TEXT;
75	BEGIN
76	  -- RBAC: só admin ou master
77	  SELECT ur.name INTO v_role_name
78	  FROM public.profiles p
79	  LEFT JOIN public.user_roles ur ON ur.id = p.role_id
80	  WHERE p.user_id = v_user_id;
81	
82	  IF v_role_name IS NULL OR LOWER(v_role_name) NOT IN ('admin', 'administrador', 'master') THEN
83	    RAISE EXCEPTION 'drp_rbac_denied: apenas admin/master pode gerar requisições via DRP (role=%)', v_role_name
84	      USING ERRCODE = '42501';
85	  END IF;
86	
87	  -- Validações estruturais
88	  IF v_data_chegada IS NULL THEN
89	    RAISE EXCEPTION 'drp_data_chegada_invalida' USING ERRCODE = '22023';
90	  END IF;
91	  IF v_data_durar_ate IS NULL THEN
92	    RAISE EXCEPTION 'drp_data_durar_ate_invalida' USING ERRCODE = '22023';
93	  END IF;
94	  IF (v_data_durar_ate - v_data_chegada) > 5 THEN
95	    RAISE EXCEPTION 'drp_horizonte_excede_validade: shelf-life uniforme 5d (chegada=%, durar_ate=%)',
96	      v_data_chegada, v_data_durar_ate USING ERRCODE = '22023';
97	  END IF;
98	  IF v_plans IS NULL OR jsonb_array_length(v_plans) = 0 THEN
99	    RAISE EXCEPTION 'drp_plans_vazio' USING ERRCODE = '22023';
100	  END IF;
101	
102	  -- Itera sobre cada plano de loja
103	  FOR v_plan IN SELECT * FROM jsonb_array_elements(v_plans)
104	  LOOP
105	    v_loja_id := (v_plan->>'loja_id')::INTEGER;
106	    v_loja_nome := v_plan->>'loja_nome';
107	    v_idem_key := v_plan->>'idempotency_key';
108	
109	    IF v_idem_key IS NULL OR length(v_idem_key) < 8 THEN
110	      RAISE EXCEPTION 'drp_idempotency_key_invalida (loja=%)', v_loja_nome USING ERRCODE = '22023';
111	    END IF;
112	    IF v_loja_nome IS NULL OR length(v_loja_nome) = 0 THEN
113	      RAISE EXCEPTION 'drp_loja_nome_invalida (loja_id=%)', v_loja_id USING ERRCODE = '22023';
114	    END IF;
115	
116	    -- Idempotency check: já existe requisição com essa chave?
117	    SELECT id INTO v_existing_id
118	    FROM public.requisicoes
119	    WHERE idempotency_key = v_idem_key;
120	
121	    IF v_existing_id IS NOT NULL THEN
122	      -- Já existe, retorna info dela
123	      SELECT
124	        COUNT(*)::INTEGER,
125	        COALESCE(SUM(quantidade_solicitada), 0)::INTEGER
126	      INTO v_qtd_itens, v_qtd_unidades
127	      FROM public.requisicoes_itens
128	      WHERE requisicao_id = v_existing_id;
129	
130	      v_result_item := jsonb_build_object(
131	        'id', v_existing_id,
132	        'loja_id', v_loja_id,
133	        'loja_nome', v_loja_nome,
134	        'qtd_itens', v_qtd_itens,
135	        'qtd_unidades', v_qtd_unidades,
136	        'idempotent_hit', true
137	      );
138	      v_results := v_results || jsonb_build_array(v_result_item);
139	      CONTINUE;
140	    END IF;
141	
142	    -- Cria a requisicao
143	    v_obs := format('Gerado via DRP — chegada=%s · durar_até=%s', v_data_chegada, v_data_durar_ate);
144	    INSERT INTO public.requisicoes (
145	      nome, solicitante, preparador,
146	      loja_solicitante, loja_preparadora,
147	      data_pedido, data_recebimento,
148	      user_id, status, idempotency_key
149	    )
150	    VALUES (
151	      format('DRP %s · %s', to_char(v_data_chegada, 'YYYY-MM-DD'), v_loja_nome),
152	      v_user_name,
153	      v_preparador,
154	      v_loja_nome,
155	      v_preparador,
156	      CURRENT_DATE,
157	      v_data_chegada,
158	      v_user_id,
159	      'em_fila',
160	      v_idem_key
161	    )
162	    RETURNING id INTO v_new_req_id;
163	
164	    -- Cria os itens
165	    v_qtd_itens := 0;
166	    v_qtd_unidades := 0;
167	    FOR v_item IN SELECT * FROM jsonb_array_elements(v_plan->'items')
168	    LOOP
169	      IF (v_item->>'quantidade_solicitada')::INTEGER <= 0 THEN
170	        CONTINUE; -- ignora itens com qty 0 (não cria linha vazia)
171	      END IF;
172	
173	      INSERT INTO public.requisicoes_itens (
174	        requisicao_id, nome_produto,
175	        quantidade_solicitada, quantidade_enviada,
176	        observacao, ordem
177	      )
178	      VALUES (
179	        v_new_req_id,
180	        v_item->>'nome_produto',
181	        (v_item->>'quantidade_solicitada')::INTEGER,
182	        '',
183	        COALESCE(v_item->>'observacao', v_obs),
184	        COALESCE((v_item->>'ordem')::INTEGER, 0)
185	      );
186	
187	      v_qtd_itens := v_qtd_itens + 1;
188	      v_qtd_unidades := v_qtd_unidades + (v_item->>'quantidade_solicitada')::INTEGER;
189	    END LOOP;
190	
191	    -- Se nenhum item válido, rollback dessa requisição (evita req vazia)
192	    IF v_qtd_itens = 0 THEN
193	      DELETE FROM public.requisicoes WHERE id = v_new_req_id;
194	      CONTINUE;
195	    END IF;
196	
197	    v_result_item := jsonb_build_object(
198	      'id', v_new_req_id,
199	      'loja_id', v_loja_id,
200	      'loja_nome', v_loja_nome,
201	      'qtd_itens', v_qtd_itens,
202	      'qtd_unidades', v_qtd_unidades,
203	      'idempotent_hit', false
204	    );
205	    v_results := v_results || jsonb_build_array(v_result_item);
206	  END LOOP;
207	
208	  RETURN jsonb_build_object('requisicoes', v_results);
209	END;
210	$$;
