91	function dateISOFromName(name: string) {
92	  const s = String(name || '');
93	  const m = s.match(/(\d{2})[/-](\d{2})[/-](\d{2,4})$/);
94	  if (!m) return null;
95	  const dd = Number(m[1]);
96	  const mm = Number(m[2]);
97	  const yy = m[3].length === 2 ? Number(`20${m[3]}`) : Number(m[3]);
98	  const d = new Date(yy || 0, (mm || 1) - 1, dd || 1);
99	  const y = d.getFullYear();
100	  const mo = String(d.getMonth() + 1).padStart(2, '0');
101	  const da = String(d.getDate()).padStart(2, '0');
102	  return `${y}-${mo}-${da}`;
103	}
104	
105	function parseISODateLocal(iso: string) {
106	  const [y, m, d] = iso.split('-').map(Number);
107	  return new Date(y || 0, (m || 1) - 1, d || 1, 12, 0, 0, 0);
108	}
109	
110	function formatTime(ts: string) {
111	  const s = String(ts || '');
112	  let d = new Date(s);
113	  if (isNaN(d.getTime())) {
114	    const parts = s.split(/[T\s]/);
115	    if (parts.length >= 2) {
116	      const [datePart, timePart] = parts;
117	      const [yy, mm, dd] = datePart.split('-').map((n) => Number(n));
118	      const [hh, mi] = timePart.split(':').map((n) => Number(n));
119	      d = new Date(yy || 0, (mm || 1) - 1, dd || 1, hh || 0, mi || 0, 0);
120	    } else {
121	      const [yy, mm, dd] = s.split('-').map((n) => Number(n));
122	      d = new Date(yy || 0, (mm || 1) - 1, dd || 1);
123	    }
124	  }
125	  return d.toLocaleTimeString('pt-BR', {
126	    timeZone: 'America/Sao_Paulo',
127	    hour: '2-digit',
128	    minute: '2-digit',
129	  });
130	}
